/* generated by tools/make_voices.py: voice sprite timings and lip-sync envelopes (30 fps) */
const VOICE_DATA = {"file":"voice/ep03.mp3","lines":{"ep03_001":{"who":"TAKUTO","text":"Previously. I made it to Ashford, and the Guild's magic cube called me an error.","mono":true,"off":0.25,"dur":4.843,"env":"00166642567744313332200000155667775611363145654443101321100000000035553212799866313234454553143200000333320012155542234433310244543211000000000000"},"ep03_002":{"who":"TAKUTO","text":"A girl with my hair beat me in a duel, because my axe refuses to block.","mono":true,"off":5.4927,"dur":4.373,"env":"022116999754721034443321234443321101433210133333332102444322110000000012044323443320023443102211211001232222223112210235542000000000"},"ep03_003":{"who":"TAKUTO","text":"Haruki was here. Two years ago. He got into a golden carriage and waved.","mono":true,"off":10.266,"dur":4.971,"env":"001599865774001134443243331033433220015245422454433331133311000000000000002312998454422244210147776512433211245444332112233332344443210000000000000000"},"ep03_004":{"who":"TAKUTO","text":"And to follow him, I have to become a Hunter.","mono":true,"off":15.6367,"dur":2.667,"env":"02436211169899777753234322210000345434553102312310134343211254420422211000000000"},"ep03_005":{"who":"NEMU","text":"You're sharpening an axe that can cut through anything.","mono":false,"off":18.7033,"dur":3.52,"env":"0036544443778502644443210000000000029731797410000233320000000003302287502246100021687541796652002111000000"},"ep03_006":{"who":"TAKUTO","text":"It calms me down.","mono":false,"off":22.6233,"dur":1.237,"env":"06601349998753466328876543211000000000"},"ep03_007":{"who":"NEMU","text":"You're nervous.","mono":false,"off":24.2607,"dur":0.875,"env":"001898767887611331123220000"},"ep03_008":{"who":"TAKUTO","text":"I've never taken an exam where failing means dying.","mono":false,"off":25.5353,"dur":3.2,"env":"025513568914610416740144443321222555543211000002431110656643333333434332300456543110000000000000"},"ep03_009":{"who":"NEMU","text":"Mm. It's just like school, except the teacher is a desert.","mono":false,"off":29.1353,"dur":4.501,"env":"0279778776654320000000000000000000181231456331135752122221246653321100000000000000230212574000151041552044233322135243134543311110010000"},"ep03_010":{"who":"TAKUTO","text":"Did you take it?","mono":false,"off":34.0367,"dur":1.024,"env":"0044335623389861145421000000000"},"ep03_011":{"who":"NEMU","text":"Three times. I died twice.","mono":false,"off":35.4607,"dur":2.283,"env":"002199704277766433211432000000000000685058665552002410444221012221000"},"ep03_012":{"who":"TAKUTO","text":"That's not comforting.","mono":false,"off":38.1433,"dur":1.259,"env":"00698144499841026976311444321111000000"},"ep03_013":{"who":"NEMU","text":"The third time I slept through the Fiend attack and woke up with a license. Some people are lucky.","mono":false,"off":39.802,"dur":7.232,"env":"0320029988840041155665544420377343320454100210011398615211015899865340232433210000000000000000005877689840335642000001503432344443232210000233200000000000000000000000000000012236988623145302432110005764344200211000000"},"ep03_014":{"who":"TAKUTO","text":"You're making that up.","mono":false,"off":47.434,"dur":1.195,"env":"013767899821145553676646531000000000"},"ep03_015":{"who":"NEMU","text":"...A little.","mono":false,"off":49.0287,"dur":0.811,"env":"0029854788722232100000000"},"ep03_016":{"who":"NEMU","text":"Rin's good, you know. She's mean because she's scared of losing people. That's all.","mono":false,"off":50.2393,"dur":5.931,"env":"0079976643210137775320100001553321111000000000000000000123365324888776542340234434243322211355544315100256654324432020330021000000000000000000000000000000001443101323332211000000"},"ep03_017":{"who":"TAKUTO","text":"I know. I've met that kind of person before.","mono":false,"off":56.57,"dur":2.581,"env":"002777778899864210004653587710186301465551011476465345324211135543210000000000"},"ep03_018":{"who":"NEMU","text":"In a mirror?","mono":false,"off":59.5513,"dur":0.832,"env":"0477987677776332211100000"},"ep03_019":{"who":"TAKUTO","text":"Go to sleep, Nemu.","mono":false,"off":60.7833,"dur":1.344,"env":"01598654322575410134554454443211000000000"},"ep03_020":{"who":"EXAMINER","text":"Applicants! Welcome to the Bramble Wastes. Your exam is simple.","mono":false,"off":62.5273,"dur":3.712,"env":"4653013721299431221138665011854322436104765555346542686654222002210001488787212227644543452222176441047654200000"},"ep03_021":{"who":"EXAMINER","text":"Somewhere in that canyon is a Fiend core, marked with a Guild flag. Bring it back by sunset tomorrow.","mono":false,"off":66.6393,"dur":5.739,"env":"02227743355566335430001244434565332342451000243323200116555441123655410112614510007765431210056544444311000000000008945640045331000254422224443322266300224345545445433310000"},"ep03_022":{"who":"EXAMINER","text":"Lesser Fiends only in the exam zone. If you meet anything bigger, fire your flare and run.","mono":false,"off":72.778,"dur":5.077,"env":"016963327510165544424100766544555853356662023266453333287655432100000000371245456412116545205544109810886410000644457632571111476556655433278754211100000"},"ep03_023":{"who":"TAKUTO","text":"What if we can't run?","mono":false,"off":78.2553,"dur":1.237,"env":"01499972154112566421345543210000000000"},"ep03_024":{"who":"EXAMINER","text":"Then you fail. Permanently.","mono":false,"off":79.8927,"dur":1.877,"env":"006956566221167568887673001247774686885203587542220000000"},"ep03_025":{"who":"RIN","text":"Don't slow me down.","mono":false,"off":82.17,"dur":1.152,"env":"05997324439889872286554433320000000"},"ep03_026":{"who":"TAKUTO","text":"Don't tie me to a rock.","mono":false,"off":83.722,"dur":1.451,"env":"00598641345777666413135543577642000000000000"},"ep03_027":{"who":"RIN","text":"Don't give me ideas.","mono":false,"off":85.5727,"dur":1.323,"env":"0499842039616877666511555543322222100000"},"ep03_028":{"who":"NEMU","text":"Good luck. Come back with all your limbs.","mono":false,"off":87.2953,"dur":2.56,"env":"03595114664310001000000000002149996486532001032130576763344323443211003433000"},"ep03_029":{"who":"TAKUTO","text":"That's the bar?","mono":false,"off":90.2553,"dur":0.981,"env":"005771330763898775332111000000"},"ep03_030":{"who":"NEMU","text":"It's a high bar, out here.","mono":false,"off":91.6367,"dur":1.664,"env":"01136652257889503654433210000000399521211422100000"},"ep03_031":{"who":"SIEG","text":"Rin. Watch his left side. He never watches it.","mono":false,"off":93.7007,"dur":3.115,"env":"0798765554445566555313357644766510232176555544432000000000499875546656555442132754344320110000"},"ep03_032":{"who":"RIN","text":"Why would I watch his anything?","mono":false,"off":97.2153,"dur":1.621,"env":"0367788479577873477640242544225665300332221000000"},"ep03_033":{"who":"SIEG","text":"Because if he dies, you fail too.","mono":false,"off":99.2367,"dur":2.304,"env":"0852597555641176543665555555554321000000587410665555531328654322210000"},"ep03_034":{"who":"RIN","text":"...Fine. Left side.","mono":false,"off":101.9407,"dur":1.216,"env":"0011998999998974013437654444310000000"},"ep03_035":{"who":"VALENTINE","text":"A good-luck charm, darling. From Tofu. He insisted.","mono":false,"off":103.5567,"dur":3.2,"env":"034115960246730000323544443333135555433322200233211145530001211100000024444233242220121100000000"},"ep03_036":{"who":"TAKUTO","text":"It's a pebble with a face drawn on it.","mono":false,"off":107.1567,"dur":2.091,"env":"042246114698268633414211057543233101244554444333221110000000000"},"ep03_037":{"who":"VALENTINE","text":"It is a very lucky pebble. Tofu drew the face himself. He has no hands, so it took him all night.","mono":false,"off":109.6473,"dur":5.163,"env":"05888346447425776554456201032012430132210000000000021699311452236641410056642323442432566321000000005556442666642255554332233234300332013443333333222001100"},"ep03_038":{"who":"NEMU","text":"The face is crying.","mono":false,"off":115.21,"dur":1.365,"env":"01610039875312110343301114655543211100000"},"ep03_039":{"who":"VALENTINE","text":"The face is moved. There is a difference.","mono":false,"off":116.9753,"dur":2.453,"env":"05400099976223254227787775442100200000577774255117640002433210111000000000"},"ep03_040":{"who":"TAKUTO","text":"...Tell him thank you.","mono":false,"off":119.8287,"dur":1.237,"env":"00135997675541018655300033211110000000"},"ep03_041":{"who":"VALENTINE","text":"Come back alive, Takuto. Errors are so rare. I would hate to lose my favourite.","mono":false,"off":121.466,"dur":4.693,"env":"014787289830145555444410021442000430221322222000000000003676666534333534455422455432221000134342112543101223335443214433310024443001211001000"},"ep03_042":{"who":"NEMU","text":"Come back with food.","mono":false,"off":126.5593,"dur":1.216,"env":"0226998658765301144121117753211120000"},"ep03_043":{"who":"TAKUTO","text":"In that order?","mono":false,"off":128.1753,"dur":0.939,"env":"04676798623589853432110000000"},"ep03_044":{"who":"NEMU","text":"Either order is fine.","mono":false,"off":129.514,"dur":1.536,"env":"02393585301798724321000165342005654432110000000"},"ep03_045":{"who":"TAKUTO","text":"So. Rin Ashveil.","mono":false,"off":131.45,"dur":1.323,"env":"0023698853588654466533105644321100000000"},"ep03_046":{"who":"RIN","text":"Don't.","mono":false,"off":133.1727,"dur":0.597,"env":"059998775222110000"},"ep03_047":{"who":"TAKUTO","text":"I haven't said anything.","mono":false,"off":134.17,"dur":1.429,"env":"0354447992553332875320456530022110000000000"},"ep03_048":{"who":"RIN","text":"You were going to say something about the hair.","mono":false,"off":135.9993,"dur":2.155,"env":"02555841498776523232236553222443102444414543003212333211100000000"},"ep03_049":{"who":"TAKUTO","text":"I was going to say we should talk about a plan.","mono":false,"off":138.554,"dur":2.709,"env":"0015656531169765544333225544321001333323101213785113234323101024433210000000000000"},"ep03_050":{"who":"RIN","text":"...Oh.","mono":false,"off":141.6633,"dur":0.533,"env":"0469999865420000"},"ep03_051":{"who":"TAKUTO","text":"And also the hair.","mono":false,"off":142.5967,"dur":1.131,"env":"0456898433365335324554311100000000"},"ep03_052":{"who":"RIN","text":"I knew it.","mono":false,"off":144.1273,"dur":0.811,"env":"0578899999877541022100000"},"ep03_053":{"who":"TAKUTO","text":"Plan. You tie things up. I break things. We don't break each other.","mono":false,"off":145.338,"dur":3.627,"env":"0115989998776554053588762116655544788510000000268429982011187654333331135476531167621132154542221000000000000"},"ep03_054":{"who":"RIN","text":"That's not a plan. That's a list of hobbies.","mono":false,"off":149.3647,"dur":2.133,"env":"0774033699988301488766555531676123766862325202355551343212210000"},"ep03_055":{"who":"TAKUTO","text":"It's more of a plan than you had.","mono":false,"off":151.898,"dur":1.707,"env":"0522505688972730113655554444343332344321100000000000"},"ep03_056":{"who":"RIN","text":"My plan was to leave you at the entrance.","mono":false,"off":154.0047,"dur":2.112,"env":"0489601169999988777330376568776235768600454356642214322023220000"},"ep03_057":{"who":"TAKUTO","text":"See? That one's worse.","mono":false,"off":156.5167,"dur":1.301,"env":"0012476651898524554223676421112110000000"},"ep03_058":{"who":"RIN","text":"Stop. Brambles. Don't touch them, the thorns are poisoned.","mono":false,"off":158.218,"dur":3.179,"env":"012299886000048877897376653220279742032560143126555534410037766666533530003665652323321110000000"},"ep03_059":{"who":"TAKUTO","text":"Everything here is poisoned or wants to eat me.","mono":false,"off":161.7967,"dur":2.816,"env":"0364146511364443235444443300113897653333222100000356346652311301333200111100000000000"},"ep03_060":{"who":"RIN","text":"Welcome to the March.","mono":false,"off":165.0127,"dur":1.216,"env":"0489860127775234476665543320022210000"},"ep03_061":{"who":"TAKUTO","text":"Can't I just break them?","mono":false,"off":166.6287,"dur":1.365,"env":"01177878873465300599741102432221110000000"},"ep03_062":{"who":"RIN","text":"You can break one. There are ten thousand.","mono":false,"off":168.394,"dur":2.155,"env":"03512699618899301037665543204767510422566640055444433233221100000"},"ep03_063":{"who":"TAKUTO","text":"I can break ten thousand.","mono":false,"off":170.9487,"dur":1.557,"env":"13420265425974000315443203444333222110000000000"},"ep03_064":{"who":"RIN","text":"Slowly. While the Lesser Fiends hear you and come for lunch.","mono":false,"off":172.906,"dur":2.923,"env":"0132489899667542000178728768733345200356543104665434554433440114544111443444332101221000"},"ep03_065":{"who":"TAKUTO","text":"...We go around.","mono":false,"off":176.2287,"dur":1.024,"env":"0254229998764666553211111000000"},"ep03_066":{"who":"RIN","text":"We go around.","mono":false,"off":177.6527,"dur":1.024,"env":"0463049788764565443333212100000"},"ep03_067":{"who":"RIN","text":"Stop. Something's moving behind the rocks.","mono":false,"off":179.0767,"dur":2.133,"env":"0112998764000233775217675237787436653633555545336543211001221000"},"ep03_068":{"who":"TAKUTO","text":"Not again.","mono":false,"off":181.61,"dur":0.875,"env":"013579777229975432100000000"},"ep03_069":{"who":"RIN","text":"A Shieldbearer. A lone one. Lesser class.","mono":false,"off":182.8847,"dur":2.133,"env":"0224436798520677766402566688877655544432345323341022442110221000"},"ep03_070":{"who":"TAKUTO","text":"I broke one of these on my first day.","mono":false,"off":185.418,"dur":2.155,"env":"02441138996101244431123223222333333331000344323200332110000000000"},"ep03_071":{"who":"RIN","text":"Then this is your second day. Go left, I'll bind it from the right.","mono":false,"off":187.9727,"dur":3.648,"env":"04889998983432554336643443751126541454433210000004999779985311111045775206766665362011455543354332210110000000"},"ep03_072":{"who":"RIN","text":"Your LEFT!","mono":false,"off":192.0207,"dur":0.768,"env":"049988998764111021000000"},"ep03_073":{"who":"TAKUTO","text":"You said go left! I went left!","mono":false,"off":193.1887,"dur":1.792,"env":"003344397213887346654200113443443112344211000000000000"},"ep03_074":{"who":"RIN","text":"MY left!","mono":false,"off":195.3807,"dur":0.747,"env":"06789899886511102200000"},"ep03_075":{"who":"TAKUTO","text":"How was I supposed to know that?!","mono":false,"off":196.5273,"dur":1.877,"env":"001589875697358665433301455431124555553243211000000000000"},"ep03_076":{"who":"RIN","text":"Fine! Your left, my right! Count of three! One...","mono":false,"off":198.8047,"dur":2.517,"env":"0018877888888337757974110466675366555203011466524111146554423544322100000000"},"ep03_077":{"who":"RIN","text":"Two!","mono":false,"off":201.722,"dur":0.597,"env":"135999865543100000"},"ep03_078":{"who":"TAKUTO","text":"Three!","mono":false,"off":202.7193,"dur":0.683,"env":"001246998654321000000"},"ep03_079":{"who":"RIN","text":"...Huh. That worked.","mono":false,"off":203.802,"dur":1.067,"env":"02358897387643468664300022100000"},"ep03_080":{"who":"TAKUTO","text":"Don't sound so surprised.","mono":false,"off":205.2687,"dur":1.621,"env":"0008986413397664137642333011577653211111100000000"},"ep03_081":{"who":"RIN","text":"I'm surprised it worked with YOU.","mono":false,"off":207.29,"dur":1.664,"env":"04799644750013777786305732587500125301444322100000"},"ep03_082":{"who":"WICK","text":"Boo!","mono":false,"off":209.354,"dur":0.533,"env":"0599888776542000"},"ep03_083":{"who":"TAKUTO","text":"AAH!","mono":false,"off":210.2873,"dur":0.533,"env":"1468986643100000"},"ep03_084":{"who":"RIN","text":"Fiend!","mono":false,"off":211.2207,"dur":0.661,"env":"00599999876445310000"},"ep03_085":{"who":"WICK","text":"Whoa whoa whoa! Not a Fiend! Human! Mostly human! Applicant number forty-four!","mono":false,"off":212.282,"dur":4.181,"env":"047876349888535877654555776541103555444232115766655545666645413542225644322110016730241163235435421125553431113322211000000000"},"ep03_086":{"who":"RIN","text":"Your head is on fire.","mono":false,"off":216.8633,"dur":1.301,"env":"0389522368748546665411155544432110000000"},"ep03_087":{"who":"WICK","text":"It's always on fire! It's my Brand! It doesn't hurt! Please put the knife down!","mono":false,"off":218.5647,"dur":4.032,"env":"0424599868765777641109986666541252242577675217665544420003316754644337874100000137776430164046656554100355432211100000000"},"ep03_088":{"who":"TAKUTO","text":"Rin.","mono":false,"off":222.9967,"dur":0.64,"env":"00258998644320000000"},"ep03_089":{"who":"RIN","text":"...Fine.","mono":false,"off":224.0367,"dur":0.704,"env":"0322179877665443100000"},"ep03_090":{"who":"WICK","text":"Thank you. Hiro Aoyama. Everyone calls me Wick, for obvious reasons.","mono":false,"off":225.1407,"dur":4.16,"env":"01988611287664228887799843877888777766654322220000007943897777612268874427764675101101463156763245555313565443321113431000000"},"ep03_091":{"who":"TAKUTO","text":"Hiro Aoyama? That's a Japanese name.","mono":false,"off":229.7007,"dur":2.859,"env":"00157775799710667777764544444422111000000016504432156753014444433321454321100000000000"},"ep03_092":{"who":"WICK","text":"Wait. You said Japanese. Nobody here says Japanese.","mono":false,"off":232.9593,"dur":3.051,"env":"04787720256335863259983046666543222210002577883398465313666322554201467610444322111121000000"},"ep03_093":{"who":"TAKUTO","text":"Kirishima Takuto. Nerima. Tokyo.","mono":false,"off":236.41,"dur":2.965,"env":"01287576785577777720479510155204799632110000001578998567877766530359851112433210000000000"},"ep03_094":{"who":"WICK","text":"No way. NO WAY. Osaka! I'm from Osaka! Tennoji! You're Skyfallen!","mono":false,"off":239.7753,"dur":4.117,"env":"0489996499887778888846977620388655685113665410026875257877554587301465420458788887776423344433434521686531145321111000000000"},"ep03_095":{"who":"TAKUTO","text":"You too?","mono":false,"off":244.2927,"dur":0.811,"env":"0146630345999643211000000"},"ep03_096":{"who":"WICK","text":"Three years! Three years, and you're the first person who knows what a convenience store is!","mono":false,"off":245.5033,"dur":4.373,"env":"003798655688777533100126976546866544331026667456100899641001687433445446776676664312584510266642566565531433055565422211022100000000"},"ep03_097":{"who":"TAKUTO","text":"I miss the onigiri.","mono":false,"off":250.2767,"dur":1.621,"env":"0777679754105531788765554422334553442110000000000"},"ep03_098":{"who":"WICK","text":"The tuna mayo ones!","mono":false,"off":252.298,"dur":1.344,"env":"04404299788677776667775336653222222100000"},"ep03_099":{"who":"TAKUTO","text":"The tuna mayo ones.","mono":false,"off":254.042,"dur":1.429,"env":"0450273898897678787767653478642110122000000"},"ep03_100":{"who":"RIN","text":"I don't know what either of you are talking about, and I hate it.","mono":false,"off":255.8713,"dur":3.115,"env":"0475498535888884598100146753867862136667403147401255441444332010145455431135530423200210000000"},"ep03_101":{"who":"TAKUTO","text":"Where's your partner?","mono":false,"off":259.386,"dur":1.131,"env":"0036898445611249986301322111000000"},"ep03_102":{"who":"WICK","text":"Mine ran away when my head caught fire this morning. Again. Third partner this year.","mono":false,"off":260.9167,"dur":4.736,"env":"03777667765776667756987766667756536763102269621114876666524455055554432111000000000463298765443200000048887310217983025552454543233221000000000"},"ep03_103":{"who":"TAKUTO","text":"You can come with us.","mono":false,"off":266.0527,"dur":1.216,"env":"0146302966422699666541543212221000000"},"ep03_104":{"who":"RIN","text":"He can NOT.","mono":false,"off":267.6687,"dur":0.896,"env":"036402988777776442002110000"},"ep03_105":{"who":"TAKUTO","text":"He knows about tuna mayo.","mono":false,"off":268.9647,"dur":1.664,"env":"00056677896453698400341454444445555432211000000000"},"ep03_106":{"who":"RIN","text":"That is not a combat skill!","mono":false,"off":271.0287,"dur":1.536,"env":"04885796479998830247777657621442156533220000000"},"ep03_107":{"who":"WICK","text":"I can also light campfires! And see in the dark! And I'm very cheap to feed!","mono":false,"off":272.9647,"dur":4.032,"env":"0562197888443975797510118766300576554443311464444477777863288886430000000046777676338876630332653002320035432111000000000"},"ep03_108":{"who":"RIN","text":"...We leave him behind the moment he slows us down.","mono":false,"off":277.3967,"dur":2.645,"env":"05997698871159887197334888768789887775212143444159877435434117654332210000000000"},"ep03_109":{"who":"WICK","text":"Deal! I'm very fast when I'm scared, and I'm always scared!","mono":false,"off":280.442,"dur":2.752,"env":"03889987521777746987510898642146756444116766553224666777764664444115543221000000000"},"ep03_110":{"who":"WICK","text":"Okay. So. Before anything happens. I should mention I have never actually fought a Fiend.","mono":false,"off":283.594,"dur":4.736,"env":"06951127986644553988873265117964677740555666740132111332000000016744474578776433665424565426766357415763022234541016654310035543211111000000000"},"ep03_111":{"who":"RIN","text":"You have been here three years.","mono":false,"off":288.73,"dur":1.472,"env":"037994108977623666520012555434543221122200000"},"ep03_112":{"who":"WICK","text":"And I have been running for three years! Very successfully!","mono":false,"off":290.602,"dur":2.88,"env":"045898786319866679966664115620115775445543332221001148776654333133575331032321110000000"},"ep03_113":{"who":"TAKUTO","text":"Something is standing in the path.","mono":false,"off":293.882,"dur":1.685,"env":"001397511654553331065555334333332012454210000000000"},"ep03_114":{"who":"RIN","text":"Another Shieldbearer. Fine. Same as before. Takuto, the shield. I take the legs.","mono":false,"off":295.9673,"dur":4.949,"env":"05899829844443689731176666431011687777777634447777776320262111566553210000000001189501571337887426444426665444120345302265100055455443311012210000000"},"ep03_115":{"who":"WICK","text":"And me? What do I take?","mono":false,"off":301.3167,"dur":1.237,"env":"04777777648834679862426543200001100000"},"ep03_116":{"who":"RIN","text":"Cover.","mono":false,"off":302.954,"dur":0.597,"env":"016953797654320000"},"ep03_117":{"who":"TAKUTO","text":"Break.","mono":false,"off":303.9513,"dur":0.683,"env":"004799876420011000000"},"ep03_118":{"who":"WICK","text":"Why is it coming for ME?!","mono":false,"off":305.034,"dur":1.472,"env":"048997666764573002287665541125443221110000000"},"ep03_119":{"who":"RIN","text":"Because you are the one screaming!","mono":false,"off":306.906,"dur":1.664,"env":"06124994336788858853843676653441146565542221000000"},"ep03_120":{"who":"WICK","text":"Fine! FINE! Will-o'-Wisp!","mono":false,"off":308.97,"dur":1.408,"env":"0199878851199877777686688874543254100000000"},"ep03_121":{"who":"WICK","text":"Only the bones! Burn only the bones!","mono":false,"off":310.778,"dur":2.027,"env":"0566679577259866655553300058777565555535315754321111232100000"},"ep03_122":{"who":"RIN","text":"Red Thread!","mono":false,"off":313.2047,"dur":0.853,"env":"06998312237987554132100000"},"ep03_123":{"who":"TAKUTO","text":"Ruinbreaker.","mono":false,"off":314.458,"dur":1.024,"env":"0258888775289973023542100000000"},"ep03_124":{"who":"WICK","text":"I did it. I fought a Fiend. I fought a Fiend and I did not run away!","mono":false,"off":315.882,"dur":3.605,"env":"0364258955972005663116874511135654332222100000035511488553111455555543445442332555521344444334332111100000000"},"ep03_125":{"who":"TAKUTO","text":"You did good.","mono":false,"off":319.8873,"dur":0.981,"env":"013542598422279986421100000000"},"ep03_126":{"who":"RIN","text":"You burned my scarf.","mono":false,"off":321.2687,"dur":1.259,"env":"03541397766665544333114443221000000000"},"ep03_127":{"who":"WICK","text":"Only a little! It only burns what I tell it to! I told it the bones and the scarf was near the bones!","mono":false,"off":322.9273,"dur":5.291,"env":"058877887896598587410177987788631998887753275787514339755302515321210000000377245984630752598776665664521465555401899862104543467666445316765421111233200000000"},"ep03_128":{"who":"RIN","text":"...It's fine. My brother burned it worse once.","mono":false,"off":328.618,"dur":2.283,"env":"079214311887877775555677318947831398776462146553331055433101222000000"},"ep03_129":{"who":"WICK","text":"So how'd you fall through?","mono":false,"off":331.3007,"dur":1.323,"env":"0368777998745951178885101376543222100000"},"ep03_130":{"who":"TAKUTO","text":"Railway crossing. Two in the morning. The sky cracked.","mono":false,"off":333.0233,"dur":2.965,"env":"01357987537741011676533322211000241555655544555443222111123311444432001255311000000000000"},"ep03_131":{"who":"WICK","text":"Mine was a shrine. I was buying a charm for exams. The ground opened under the gate.","mono":false,"off":336.3887,"dur":4.629,"env":"0488766777669656644317776665543026767530098766656612424766666511266422445433211133200000000063159876776433674027645544334115542100200000000"},"ep03_132":{"who":"WICK","text":"Funny, right? I was buying a charm to pass exams, and now I'm taking one in a desert full of monsters.","mono":false,"off":341.418,"dur":5.632,"env":"0019877766534987763000004786774105966655565033366656423024664333322334332222231000156777666666335565223176102565555554224553103765445300004545215554443231121102210000000"},"ep03_133":{"who":"TAKUTO","text":"...Three years.","mono":false,"off":347.45,"dur":1.003,"env":"0331146997646897642212221000000"},"ep03_134":{"who":"WICK","text":"Three years.","mono":false,"off":348.8527,"dur":0.853,"env":"03689865698886542121100000"},"ep03_135":{"who":"TAKUTO","text":"Have you looked for a way back?","mono":false,"off":350.106,"dur":1.429,"env":"0037335744992022146535555421765311000000000"},"ep03_136":{"who":"WICK","text":"Everybody looks. The first year, I looked every day. Rifts, old books, fortune tellers.","mono":false,"off":351.9353,"dur":4.608,"env":"0584388539996787688621430451159984302677778666850113674367643653222210000024898641122421057776432286411331005763134653236632222122100000000"},"ep03_137":{"who":"WICK","text":"I met an old man in Fort Cinder who fell through forty years ago. Forty. He has a family here now.","mono":false,"off":356.9433,"dur":5.568,"env":"077766884665357893256766666651017862265577546643641147763011466421114777465336664444235443222000000001489998733211100000004678655410676655554421466544443222110000000000"},"ep03_138":{"who":"WICK","text":"He told me the same thing everyone tells you, eventually.","mono":false,"off":362.9113,"dur":2.965,"env":"05335996578537443366666400766530068426765666413267664222444320015327754221332221110000000"},"ep03_139":{"who":"TAKUTO","text":"What?","mono":false,"off":366.2767,"dur":0.576,"env":"014798742011000000"},"ep03_140":{"who":"WICK","text":"Nobody goes home. Not one. Not ever. The Rifts only open one way.","mono":false,"off":367.2527,"dur":3.819,"env":"0388862696563159877554117766544221577621566553257774775133211000016447861245104666542464025554454444333211000000000"},"ep03_141":{"who":"WICK","text":"Sorry. I always say it too fast. My mom used to say I had no brakes.","mono":false,"off":371.4713,"dur":4.032,"env":"0127999888754147745887598643367675103573007543222210000000016777888778767776302443276653355445643666421475320011221000000"},"ep03_142":{"who":"TAKUTO","text":"Somebody fell through at my crossing two years ago. My friend.","mono":false,"off":375.9033,"dur":3.819,"env":"0023686654985641117765101134557641244430012666433234420414432355423311332211100000000001355411116654311000000000000"},"ep03_143":{"who":"WICK","text":"Then you're not looking for a way home. You're looking for him.","mono":false,"off":380.122,"dur":2.773,"env":"048777788689983258213664123888754777665366442221000016647831166512164234221100000000"},"ep03_144":{"who":"TAKUTO","text":"Yeah.","mono":false,"off":383.2953,"dur":0.619,"env":"0126988642122100000"},"ep03_145":{"who":"WICK","text":"That's a better thing to look for. That one, you can find.","mono":false,"off":384.314,"dur":2.731,"env":"0551686349858620466653265574011135544331000577731356555554115531155433221111000000"},"ep03_146":{"who":"RIN","text":"There. The flag. The core is at the bottom of the canyon.","mono":false,"off":387.4447,"dur":2.752,"env":"07887776106322158776665311000160121899887355652044157665556530331125545543222110000"},"ep03_147":{"who":"RIN","text":"We camp here and climb down at first light.","mono":false,"off":390.5967,"dur":2.347,"env":"04402499863111687673366221377777775286655555411116642430443321002000000"},"ep03_148":{"who":"TAKUTO","text":"Why not now?","mono":false,"off":393.3433,"dur":1.003,"env":"0159999898623687764211000000000"},"ep03_149":{"who":"RIN","text":"Because things in the Wastes hunt by sound at night, and you two never stop talking.","mono":false,"off":394.746,"dur":4.544,"env":"04118943300197788635777764487765322112112665210047552332655554631355443310100000257666510323666665564243222154430001045420112111000000000"},"ep03_150":{"who":"WICK","text":"She's got us there.","mono":false,"off":399.69,"dur":1.088,"env":"012896432999777532047543332210000"},"ep03_151":{"who":"WICK","text":"And then the vending machine ate my coin, so I kicked it, and the security guard...","mono":false,"off":401.178,"dur":4.053,"env":"03888788843986767766764335776413764137764012177655444344466765201118500035652000004565454331114776453215555431100000000000"},"ep03_152":{"who":"WICK","text":"Anyway, he never caught me. I was the fastest kid in Tennoji. Still am. Fear is a great coach.","mono":false,"off":405.6313,"dur":5.376,"env":"046676676666436666673472011799402221110000016655306200597643024431011775465523146566665554322233211123214665544444310000366655333334213654100115532100121000000000"},"ep03_153":{"who":"TAKUTO","text":"Do you miss it? Osaka?","mono":false,"off":411.4073,"dur":1.707,"env":"0034577799843399730000379753338774012565211100000000"},"ep03_154":{"who":"WICK","text":"Every day. My mom ran a little okonomiyaki shop. Four tables. I used to flip the pancakes when she was tired.","mono":false,"off":413.514,"dur":6.592,"env":"058326764498776642103676677776776566776666655757741168621576666566555565102434327655310000000027887224477642332223320000000000466678533431149600061237766611264310330453324344312466543221100000000000"},"ep03_155":{"who":"WICK","text":"Sometimes I make them here. No flour that tastes right. No sauce. They're terrible.","mono":false,"off":420.506,"dur":4.437,"env":"02397723898776579778887200577752365432210000068999311179997887375104167654332147875530025777764445877644310665204277665223221000000000"},"ep03_156":{"who":"WICK","text":"I make them anyway. So I don't forget the smell.","mono":false,"off":425.3433,"dur":2.368,"env":"057888951009764137887767654432344788748752115534850024431654432210000000"},"ep03_157":{"who":"TAKUTO","text":"Make me one sometime.","mono":false,"off":428.1113,"dur":1.408,"env":"0279500798799874555975523467532110000000000"},"ep03_158":{"who":"WICK","text":"They're really bad.","mono":false,"off":429.9193,"dur":1.024,"env":"0789865799967862687655421310000"},"ep03_159":{"who":"TAKUTO","text":"I'll eat it anyway.","mono":false,"off":431.3433,"dur":1.195,"env":"038983025756923577766455321110000000"},"ep03_160":{"who":"WICK","text":"...Okay. Okay! Deal! I knew I liked you.","mono":false,"off":432.938,"dur":2.155,"env":"03895025987548950239766425677764124677776775466541033221110000000"},"ep03_161":{"who":"RIN","text":"He's asleep.","mono":false,"off":435.4927,"dur":0.917,"env":"0389846963325676431001100000"},"ep03_162":{"who":"TAKUTO","text":"He fell asleep in the middle of his own story.","mono":false,"off":436.81,"dur":2.624,"env":"0023104997545233211254320000000244444455355541332243333322310333321110000000000"},"ep03_163":{"who":"RIN","text":"His head is still on fire. Is that safe?","mono":false,"off":439.834,"dur":2.304,"env":"0384326994873331687778764103766554433200077420776401332755432000000000"},"ep03_164":{"who":"TAKUTO","text":"It kept us warm.","mono":false,"off":442.538,"dur":1.195,"env":"044102599101663411356655421111000000"},"ep03_165":{"who":"RIN","text":"...It did.","mono":false,"off":444.1327,"dur":0.768,"env":"058821049987652132000000"},"ep03_166":{"who":"TAKUTO","text":"Nemu told me about your brother.","mono":false,"off":445.3007,"dur":1.899,"env":"035778877876164289862355543177630134213788312210000000000"},"ep03_167":{"who":"RIN","text":"Nemu has a big mouth for someone who sleeps all day.","mono":false,"off":447.5993,"dur":3.051,"env":"05789999999887324634620784026777664310110343335765555534533331553012212555541145432110000000"},"ep03_168":{"who":"TAKUTO","text":"I'm sorry.","mono":false,"off":451.05,"dur":0.896,"env":"156663334988865432110000000"},"ep03_169":{"who":"RIN","text":"Don't be sorry. Be useful. That's what he would have said.","mono":false,"off":452.346,"dur":2.773,"env":"059962286343798888876630475557884331046533100068621311783366584613326543311000000000"},"ep03_170":{"who":"RIN","text":"He used to say a Hunter is just a person who stands between a Fiend and someone who can't run.","mono":false,"off":455.5193,"dur":5.163,"env":"01667885302544359989984228886023566623642013853125101577522244443203642314766664201502167663110047776666642235533347655444431143011444310244432210000000000"},"ep03_171":{"who":"TAKUTO","text":"That's a good thing to be.","mono":false,"off":461.082,"dur":1.429,"env":"0037611452137971001433321221133321100000000"},"ep03_172":{"who":"RIN","text":"It got him killed.","mono":false,"off":462.9113,"dur":1.067,"env":"15206998559883116766443222100000"},"ep03_173":{"who":"TAKUTO","text":"It saved somebody first, though. Didn't it?","mono":false,"off":464.378,"dur":2.389,"env":"052033398883233765497454111399753300343321110000006945665432100000000000"},"ep03_174":{"who":"RIN","text":"...A whole caravan. Eleven people.","mono":false,"off":467.1673,"dur":1.963,"env":"03652148997212256677315544430046667761465411134300132110000"},"ep03_175":{"who":"TAKUTO","text":"Then he was right.","mono":false,"off":469.53,"dur":1.045,"env":"00567876684333899853210011000000"},"ep03_176":{"who":"RIN","text":"Why do you even want this? You could stay in Ashford, sweep floors, live a quiet life.","mono":false,"off":470.9753,"dur":4.885,"env":"037893677777753888776774101443122210000004741592344078788887405776343201665521233306630011116877655542323465555234010255445412344432210000000000000"},"ep03_177":{"who":"TAKUTO","text":"Because the axe came out for me. That has to be for something.","mono":false,"off":476.2607,"dur":3.392,"env":"032059621154203455410220143344443000122221110000000000355333355331023133210122222443310021000000000000"},"ep03_178":{"who":"AKURO","text":"It was for something, boy. For me.","mono":true,"off":480.0527,"dur":2.197,"env":"025994479642357544488962134866553489989854320003666555545321100000"},"ep03_179":{"who":"RIN","text":"You do that a lot. Go quiet and look at the axe.","mono":false,"off":482.65,"dur":2.645,"env":"02697389839876867777765420120049720116877777523566664015104542343210013431000000"},"ep03_180":{"who":"TAKUTO","text":"It talks.","mono":false,"off":485.6953,"dur":0.811,"env":"0351026899864201211000000"},"ep03_181":{"who":"RIN","text":"Very funny.","mono":false,"off":486.906,"dur":0.896,"env":"049989972216986654432000000"},"ep03_182":{"who":"TAKUTO","text":"...Yeah. Very funny.","mono":false,"off":488.202,"dur":1.28,"env":"013789642124966653111364332110000000000"},"ep03_183":{"who":"WICK","text":"Wh-what was that?","mono":false,"off":489.882,"dur":1.365,"env":"08946989998823319942465431776543101100000"},"ep03_184":{"who":"RIN","text":"The ground. Something under the ground.","mono":false,"off":491.6473,"dur":1.899,"env":"042149976777762223333765200656565455162137543322211100000"},"ep03_185":{"who":"WICK","text":"That is NOT a Lesser Fiend!","mono":false,"off":493.946,"dur":1.451,"env":"06985885588999978688543452005654322210000000"},"ep03_186":{"who":"RIN","text":"A Stonehide Behemoth. A Greater Fiend. In the exam zone.","mono":false,"off":495.7967,"dur":3.435,"env":"13344298887446773105411156665544310010451169865631115655443331100000017787778832237655554336543322100000"},"ep03_187":{"who":"TAKUTO","text":"The examiner said fire the flare and run.","mono":false,"off":499.6313,"dur":2.347,"env":"02673234988866565454575200057655553241111665544334444555310000000000000"},"ep03_188":{"who":"RIN","text":"It's between us and the canyon exit.","mono":false,"off":502.378,"dur":2.069,"env":"051220271329998997523331036766311466666666523563222343100100000"},"ep03_189":{"who":"WICK","text":"So we fire the flare and run... somewhere else?","mono":false,"off":504.8473,"dur":2.24,"env":"01386882019866662630136666655555665444320123375665443321122210000000"},"ep03_190":{"who":"RIN","text":"Move!","mono":false,"off":507.4873,"dur":0.597,"env":"058999876311110000"},"ep03_191":{"who":"TAKUTO","text":"Its skin is rock. Swords won't cut it.","mono":false,"off":508.4847,"dur":2.325,"env":"1530443019987765432368899632000000233877762235664201256623210000000000"},"ep03_192":{"who":"RIN","text":"Swords won't. You might.","mono":false,"off":511.21,"dur":1.323,"env":"0124989972323588764101455554332001000000"},"ep03_193":{"who":"TAKUTO","text":"You're trusting me?","mono":false,"off":512.9327,"dur":1.109,"env":"0136302179732102433333211100000000"},"ep03_194":{"who":"RIN","text":"I'm trusting the axe. Don't make it weird.","mono":false,"off":514.442,"dur":2.283,"env":"047897132795331688776435654200123210028984367621642356554333110000000"},"ep03_195":{"who":"TAKUTO","text":"Break!","mono":false,"off":517.1247,"dur":0.64,"env":"00489976520011100000"},"ep03_196":{"who":"WICK","text":"He cracked it! He cracked the rock!","mono":false,"off":518.1647,"dur":1.643,"env":"03512298765126773347411287641017556543310000000000"},"ep03_197":{"who":"RIN","text":"Takuto!","mono":false,"off":520.2073,"dur":0.939,"env":"01789840199534798765432100000"},"ep03_198":{"who":"TAKUTO","text":"I'm fine. I tried to block again.","mono":false,"off":521.546,"dur":1.984,"env":"035652226977765543102450426765252267652013214421110000000000"},"ep03_199":{"who":"RIN","text":"Stop trying to block!","mono":false,"off":523.93,"dur":1.365,"env":"01317988730032777775552477544321010000000"},"ep03_200":{"who":"RIN","text":"Red Thread! Its legs are bound! Wick, its eyes!","mono":false,"off":525.6953,"dur":2.496,"env":"028995100269888536403416888323685147555544442100157401630435544332221221000"},"ep03_201":{"who":"WICK","text":"Will-o'-Wisp! Only burns what I tell it to! Burn its eyes!","mono":false,"off":528.5913,"dur":2.88,"env":"048779999659764420001677778621876666424556403176543033454211766564144664321111321000000"},"ep03_202":{"who":"RIN","text":"It can't see and it can't move! Now, Takuto!","mono":false,"off":531.8713,"dur":2.752,"env":"05501169952455377798775002276522677765531110000578888630215752016503145433210000000"},"ep03_203":{"who":"AKURO","text":"Ah. Finally, something worth breaking.","mono":true,"off":535.0233,"dur":2.197,"env":"016768663213899898686675344587435786668964100369765211343321110000"},"ep03_204":{"who":"TAKUTO","text":"Ruinbreaker!","mono":false,"off":537.6207,"dur":0.981,"env":"013688877647986202553210000000"},"ep03_205":{"who":"RIN","text":"Hold still. Your arm is open to the bone.","mono":false,"off":539.002,"dur":2.389,"env":"006886225432698765310026793267777777543467620145423224413644332211000000"},"ep03_206":{"who":"TAKUTO","text":"What are you doing?","mono":false,"off":541.7913,"dur":1.003,"env":"0049675455315997643111000000000"},"ep03_207":{"who":"RIN","text":"Stitching it. With thread. What does it look like?","mono":false,"off":543.194,"dur":2.304,"env":"0121772154789987401366100035997763232236712644734662013443220000000000"},"ep03_208":{"who":"TAKUTO","text":"Your Brand thread?","mono":false,"off":545.898,"dur":1.109,"env":"0137822497776641122665321000000000"},"ep03_209":{"who":"RIN","text":"It ties two things together so they move as one. Skin is two things. Usually.","mono":false,"off":547.4073,"dur":4.565,"env":"14002369877320224765105666642024228762664222652666666666226421255644321000000012301998765533103166530056543343211002356653334433211000000"},"ep03_210":{"who":"TAKUTO","text":"...That actually works?","mono":false,"off":552.3727,"dur":1.259,"env":"02279977786034457754588631002221000000"},"ep03_211":{"who":"RIN","text":"My brother came home cut up so often I got very good at it. Hold. Still.","mono":false,"off":554.0313,"dur":4.437,"env":"04687159747402477764367766663011354256301333665226663111444444214553011565554114745544322210020000000000387655312344225643221000000000"},"ep03_212":{"who":"TAKUTO","text":"Ow.","mono":false,"off":558.8687,"dur":0.555,"env":"04689987532000000"},"ep03_213":{"who":"RIN","text":"You took a Behemoth to the chest and you say ow to a needle.","mono":false,"off":559.8233,"dur":3.2,"env":"026513952882983116899898740012346034278642123101000477777444587873577750314655565552342210000000"},"ep03_214":{"who":"TAKUTO","text":"The Behemoth didn't enjoy it.","mono":false,"off":563.4233,"dur":1.749,"env":"04427832158878988410049446555543447889633211000000000"},"ep03_215":{"who":"RIN","text":"...I am not enjoying it.","mono":false,"off":565.5727,"dur":1.387,"env":"016799999999725797345998775554332003100000"},"ep03_216":{"who":"TAKUTO","text":"You are smiling.","mono":false,"off":567.3593,"dur":1.045,"env":"01469955431798887643221110000000"},"ep03_217":{"who":"RIN","text":"It is the firelight. Done. Don't bend it until morning.","mono":false,"off":568.8047,"dur":3.051,"env":"05893575650721117667776454443101110016766555420006874100776653543443224445555454322111000000"},"ep03_218":{"who":"TAKUTO","text":"Thank you, Rin.","mono":false,"off":572.2553,"dur":1.024,"env":"0019987322378535976432110000000"},"ep03_219":{"who":"RIN","text":"Don't thank me. Be useful.","mono":false,"off":573.6793,"dur":1.472,"env":"059842017887312766413644457643420353221000000"},"ep03_220":{"who":"WICK","text":"We're alive. We're ALIVE!","mono":false,"off":575.5513,"dur":1.28,"env":"069998899777872247785686653222111100000"},"ep03_221":{"who":"TAKUTO","text":"Mostly.","mono":false,"off":577.2313,"dur":0.832,"env":"0136998633103544311000000"},"ep03_222":{"who":"RIN","text":"You're bleeding.","mono":false,"off":578.4633,"dur":0.875,"env":"038972178986744653331000000"},"ep03_223":{"who":"TAKUTO","text":"You're worried.","mono":false,"off":579.738,"dur":0.875,"env":"003675337998654321110000000"},"ep03_224":{"who":"RIN","text":"I'm calculating whether I pass if my partner bleeds to death.","mono":false,"off":581.0127,"dur":3.413,"env":"0589922268860149689884677665988288977740112455542443141106665101157722455313565552134134215542100000000"},"ep03_225":{"who":"TAKUTO","text":"And?","mono":false,"off":584.826,"dur":0.555,"env":"01689876534100000"},"ep03_226":{"who":"RIN","text":"Don't bleed to death.","mono":false,"off":585.7807,"dur":1.173,"env":"059984214788775133522765432000100000"},"ep03_227":{"who":"WICK","text":"Rin. That's the nicest thing you've ever said.","mono":false,"off":587.354,"dur":2.048,"env":"06988776636997122077787774325441046676635762542324443110000000"},"ep03_228":{"who":"RIN","text":"Nobody asked you, fire boy.","mono":false,"off":589.802,"dur":1.707,"env":"0467972695555355423212442111554555410454432111000000"},"ep03_229":{"who":"EXAMINER","text":"Applicants! We saw the flare... you didn't fire it. We saw the explosion.","mono":false,"off":591.9087,"dur":3.883,"env":"475400372129943132044322786164100067777776420014651462442000074457887776111004543268625685103220057767643357433100000"},"ep03_230":{"who":"EXAMINER","text":"Is that... a Stonehide Behemoth? You killed a Greater Fiend? You're applicants!","mono":false,"off":596.1913,"dur":4.032,"env":"0974208755640007433207766553466620065213655577653200000363012797427301876638411036445554211399505543004811277431233320000"},"ep03_231":{"who":"TAKUTO","text":"It was in the way.","mono":false,"off":600.6233,"dur":1.131,"env":"0652496458787775458886311100000000"},"ep03_232":{"who":"RIN","text":"He says that.","mono":false,"off":602.154,"dur":0.917,"env":"0288532998521775443200100000"},"ep03_233":{"who":"EXAMINER","text":"Greater Fiends don't come into the exam zone. We clear it every season. Something drove this one here.","mono":false,"off":603.4713,"dur":5.888,"env":"000797536511008654433231018653100136634432222665102136544333226865554332000035300213544569500006530244222234344327633200000000122696210363441138757741006822204763331466533210000"},"ep03_234":{"who":"RIN","text":"Drove it? Fiends don't take orders.","mono":false,"off":609.7593,"dur":2.005,"env":"0158999626752000000667776430476531122554013554323221122100000"},"ep03_235":{"who":"EXAMINER","text":"They don't. That's what worries me.","mono":false,"off":612.1647,"dur":1.963,"env":"00199651598766422102854123129940337776676422466554300000000"},"ep03_236":{"who":"EXAMINER","text":"You pass. All three of you. Hunters, rank F, effective immediately. Congratulations.","mono":false,"off":614.5273,"dur":5.163,"env":"03850145555532205975420112554795115665200000002984423687743215964310006664100063007730017628744565523697135865310001755315854400336768775233486433223320000"},"ep03_237":{"who":"WICK","text":"Rank F! I'm a real Hunter! Mom! I'm a Hunter!","mono":false,"off":620.09,"dur":2.432,"env":"0598741999513757864789863168744366556776676553136666311665344332110000000"},"ep03_238":{"who":"TAKUTO","text":"Rank F. For killing a Greater Fiend.","mono":false,"off":622.922,"dur":2.176,"env":"004566412247985301010042011774544432145544411104343211000000000000"},"ep03_239":{"who":"RIN","text":"Everyone starts at F. Even my brother.","mono":false,"off":625.498,"dur":2.517,"env":"0594289968999975525877224675505664321111000057844998876675117764043221000000"},"ep03_240":{"who":"RIN","text":"...You're not completely useless, Skyfallen.","mono":false,"off":628.4153,"dur":2.219,"env":"0148999983013872115853147545763331654233311766521146544333220000000"},"ep03_241":{"who":"TAKUTO","text":"That's the nicest thing you've ever said.","mono":false,"off":631.034,"dur":2.069,"env":"005983120497677877422443200264455454234552432323532110000000000"},"ep03_242":{"who":"RIN","text":"Don't get used to it.","mono":false,"off":633.5033,"dur":1.237,"env":"04998641685135677523222445432011000000"},"ep03_243":{"who":"TAKUTO","text":"Wick. How did your Brand wake up?","mono":false,"off":635.1407,"dur":1.728,"env":"0127995001112564531343213544443333331124321000000000"},"ep03_244":{"who":"WICK","text":"You really want to know? It is not a cool story.","mono":false,"off":637.2687,"dur":2.453,"env":"03644897576447863236666554310004747543366763301135453332144442321010000000"},"ep03_245":{"who":"TAKUTO","text":"Mine was a girl dying in a graveyard. Mine is not a cool story either.","mono":false,"off":640.122,"dur":4.821,"env":"0258999998757856721289997621277666665555655411376664113442210000000000000002579888877642345336656451011135555357611766654432023442122100000000000"},"ep03_246":{"who":"WICK","text":"My first winter here, I got lost in the Wastes. No coat. Just my hoodie. Three days.","mono":false,"off":645.3433,"dur":4.501,"env":"0477611399631077576534666656632788513578885331156655455532223202320000000477720229886301136541575554368654321001365633643211132100000000"},"ep03_247":{"who":"WICK","text":"On the third night, I couldn't feel my hands. I lay down in the sand and I thought, okay. This is it. I just want to be warm one more time.","mono":false,"off":650.2447,"dur":7.189,"env":"046666200397653366655522451128353013765556555325554321112322000000002666557776425766655565444345555544445544300467641144301135432210055442654334210000000000145324641046422255533555454445554444303134432111100000000000"},"ep03_248":{"who":"WICK","text":"And then I was. My whole head went up like a gas stove. Blue. I could see for a mile.","mono":false,"off":657.834,"dur":4.395,"env":"059998698775698864415777762798865589834766774016631441578763544136443321000000000006799877631016631372464564115666665542222100000000"},"ep03_249":{"who":"TAKUTO","text":"You wanted to be warm.","mono":false,"off":662.6287,"dur":1.344,"env":"00343389966612542354422456654221000000000"},"ep03_250":{"who":"WICK","text":"A Brand is what you want most, at the moment you are about to die. That is what Valentine told me.","mono":false,"off":664.3727,"dur":5.269,"env":"044159977777576523794144764788413566544334210251067888776764232767777427653033432676554321200000000005775103654259612158665555423355544323155441022111000000000"},"ep03_251":{"who":"WICK","text":"I wanted to be warm. You wanted... what did you want?","mono":false,"off":670.042,"dur":2.603,"env":"0687469977335448854467777665433563466775444111000001672343346434543210321000000"},"ep03_252":{"who":"TAKUTO","text":"...To break the thing that was killing her.","mono":false,"off":673.0447,"dur":1.941,"env":"00432399861001621105554444521234201136543332212221000000000"},"ep03_253":{"who":"WICK","text":"Huh. Yeah. That tracks.","mono":false,"off":675.386,"dur":1.237,"env":"01777669766656851021876532101222100000"},"ep03_254":{"who":"RIN","text":"Mine was a thread. I wanted to hold on to something that was falling.","mono":false,"off":677.0233,"dur":3.691,"env":"058888899988785467300116976541100000037966999832562168885597776233455466420155552552143431006755533222100000000"},"ep03_255":{"who":"WICK","text":"...Okay, so that is the saddest one. Rin wins.","mono":false,"off":681.114,"dur":2.389,"env":"059821279984328639956531443268874633013554431124776766555431111121000000"},"ep03_256":{"who":"RIN","text":"It is not a contest, Wick.","mono":false,"off":683.9033,"dur":1.579,"env":"059598449888761126666512455423211247541000000000"},"ep03_257":{"who":"WICK","text":"Everything is a contest when you are rank F.","mono":false,"off":685.882,"dur":2.219,"env":"0773699208876775650239987533776441146777777644666531555211000000000"},"ep03_258":{"who":"NEMU","text":"Welcome back. I made a sign.","mono":false,"off":688.5007,"dur":2.048,"env":"00178620427653454321100010000000003598677345533455432111000000"},"ep03_259":{"who":"TAKUTO","text":"It says welcome back, hunter's. With an apostrophe.","mono":false,"off":690.9487,"dur":3.157,"env":"03202349753226776202544325554300134441123211111100000000145145552011266743300131001210000000000"},"ep03_260":{"who":"NEMU","text":"I ran out of paint for the rest of the plural.","mono":false,"off":694.506,"dur":3.136,"env":"01253399999886525755410003117753200031000000000000012718527765213343030017204403045532211000000"},"ep03_261":{"who":"WICK","text":"You made us a sign? Nobody has ever made me a sign!","mono":false,"off":698.042,"dur":2.816,"env":"0377889779433544337776655430025788725975656643105732666665225443332254332111000000000"},"ep03_262":{"who":"NEMU","text":"I didn't make it for you. Who are you? Your head is on fire.","mono":false,"off":701.258,"dur":3.904,"env":"0113473352488813421112211221000000000000000000199888753137652100000000000000017842238874324654556552112534432111100000"},"ep03_263":{"who":"WICK","text":"Hiro Aoyama! Osaka! Hunter, rank F! Everyone calls me Wick!","mono":false,"off":705.562,"dur":3.776,"env":"017776699733767787876665665542004675554765101554321387335753655411345541000057336655641125554424543232100000000000"},"ep03_264":{"who":"NEMU","text":"...You can stand under the sign too. It is a big sign.","mono":false,"off":709.738,"dur":3.691,"env":"003813388532313899887653555443034422556665530421543100000000000000000000000028839643620486103222554322100000000"},"ep03_265":{"who":"RIN","text":"Did you wait here the whole time?","mono":false,"off":713.8287,"dur":1.685,"env":"035247864999942221577546213676531325544333220000000"},"ep03_266":{"who":"NEMU","text":"I slept here the whole time. Waiting is just sleeping where people can see you.","mono":false,"off":715.914,"dur":5.419,"env":"0153322126630122005665316311565442022343321111000000000000000000000000000000299988189755543320444330012320267520332100000000003530314620343102154232214432111000000"},"ep03_267":{"who":"TAKUTO","text":"Thanks, Nemu.","mono":false,"off":721.7327,"dur":1.152,"env":"00099754133145666655554321100000000"},"ep03_268":{"who":"NEMU","text":"Mm. You smell like rocks. Take a bath before the ceremony.","mono":false,"off":723.2847,"dur":4.693,"env":"038888887775543000000000000774444439999876534430100465322100023232000000000000000000000003158048407766542110100251115513443344555333111100000"},"ep03_269":{"who":"VALENTINE","text":"Three applicants. One Greater Fiend. Zero dead. I may cry.","mono":false,"off":728.378,"dur":3.456,"env":"00147554975001411144312430247777615663441000455443331100000014478857764125544411103444432011255332211000"},"ep03_270":{"who":"SIEG","text":"She cried at the last ceremony too.","mono":false,"off":732.234,"dur":2.219,"env":"0349523696555565310441377766555643222277777666666520217875432210000"},"ep03_271":{"who":"VALENTINE","text":"That was allergies!","mono":false,"off":734.8527,"dur":1.493,"env":"008985023896362878878862233444311211000000000"},"ep03_272":{"who":"CLERK","text":"Kirishima Takuto, Hunter rank F. Rin Ashveil, Hunter rank C, commended. Hiro Aoyama, Hunter rank F.","mono":false,"off":736.746,"dur":7.125,"env":"0048756884326988877312652005750227887776410474146446665211046543100000000000004898763477752210377787664212752265366653112232444300136565654244421100000000037987899547777887666554444444310353134324433011333110000000"},"ep03_273":{"who":"RIN","text":"Commended?","mono":false,"off":744.2713,"dur":0.789,"env":"017899999856762221000000"},"ep03_274":{"who":"VALENTINE","text":"For keeping two Skyfallen alive in the Wastes. That is harder than killing a Behemoth, darling.","mono":false,"off":745.4607,"dur":5.077,"env":"005202297017797154266644540477763002665444454557666540444432565321242003310000000000197316655123997366235551211666655442241004788744321000255543222221000"},"ep03_275":{"who":"WICK","text":"Hey!","mono":false,"off":750.938,"dur":0.576,"env":"006999877644310000"},"ep03_276":{"who":"TAKUTO","text":"She's not wrong.","mono":false,"off":751.914,"dur":1.045,"env":"01244643898533799864321110000000"},"ep03_277":{"who":"SIEG","text":"Takuto. The examiner's report says something drove that Behemoth into the zone.","mono":false,"off":753.3593,"dur":5.376,"env":"028876400159752329775533200000000000797666668655555555543157410177653113327643227543036666425865556532166310047533866665444300000000078537645754358665433221100000"},"ep03_278":{"who":"TAKUTO","text":"The axe said the same thing.","mono":false,"off":759.1353,"dur":1.515,"env":"0155478983123388234322655553006643110100000000"},"ep03_279":{"who":"SIEG","text":"...The axe said.","mono":false,"off":761.05,"dur":1.045,"env":"04896335665313224876543443210000"},"ep03_280":{"who":"TAKUTO","text":"Forget it.","mono":false,"off":762.4953,"dur":0.853,"env":"00147423999746432000000000"},"ep03_281":{"who":"SIEG","text":"No. I won't. Next time it says something, you tell me.","mono":false,"off":763.7487,"dur":3.285,"env":"089766555531367766655654211100000000187412302765566422257653226654302656543102674228865544333210000"},"ep03_282":{"who":"VALENTINE","text":"And bring Tofu a present. He sulked for two days after the error.","mono":false,"off":767.434,"dur":3.648,"env":"03783787870312677300144420014532233210100000000000463443898400020033004155523655443224632001313333444332221000"},"ep03_283":{"who":"VALENTINE","text":"Two Skyfallen on one license list. In one season. That has never happened, Sieg.","mono":false,"off":771.482,"dur":4.843,"env":"23376533312688630046654444454554676665567651222311202321012010000000002799867978733325443213233200000016742353267785064222541013331222254321010000"},"ep03_284":{"who":"SIEG","text":"Wick has been here three years. That only leaves one new one.","mono":false,"off":776.7247,"dur":3.605,"env":"0994013787641086668759776651112487555566544433431000000000498300897766666667766454367777666677764444322210000"},"ep03_285":{"who":"VALENTINE","text":"Do you know what the Guild does with its Skyfallen reports? It sends them to Saint Lumen. Sealed. And nothing comes back.","mono":false,"off":780.73,"dur":6.165,"env":"02357898889548401522687641056533134151144224776400155544444340010554320012210000000015035399895216553223443554224666653323310000000001244667653311000035778993004444211344321046432000100"},"ep03_286":{"who":"SIEG","text":"Nothing ever?","mono":false,"off":787.2953,"dur":1.109,"env":"0997652287777400377667654443110000"},"ep03_287":{"who":"VALENTINE","text":"Once. A boy with black hair, two winters ago. The Order sent a golden carriage for him personally.","mono":false,"off":788.8047,"dur":5.248,"env":"03798641243104310576776523300046531010134332200422442466513232222022222210000000000000442688736333244323103665522444211244443023102212333101244323303221111000"},"ep03_288":{"who":"SIEG","text":"Haruki. Takuto's friend.","mono":false,"off":794.4527,"dur":2.112,"env":"0159777777663115876665200001987511987339766764321587654433210000"},"ep03_289":{"who":"VALENTINE","text":"If the Saint sends a carriage for Takuto too, I want to know why before he gets in.","mono":false,"off":796.9647,"dur":4.651,"env":"04500045443366764113345553320123444441131003102136740003422223320141455332000000000015765795212565554246666433103100332231133100223322221000"},"ep03_290":{"who":"SIEG","text":"He would get in. To see his friend, he would get into anything.","mono":false,"off":802.0153,"dur":3.584,"env":"009878653676412677765444300000000397433867885431007876665555300000007887653675377746600267666531144432211000"},"ep03_291":{"who":"VALENTINE","text":"Then we had better make him strong enough to get out again.","mono":false,"off":805.9993,"dur":2.816,"env":"0499888766861029865666655201365357502689976544442000331154135653222023222220000000000"},"ep03_292":{"who":"SIEG","text":"Gideon.","mono":false,"off":809.2153,"dur":0.832,"env":"0279867777787666654210000"},"ep03_293":{"who":"VALENTINE","text":"Gideon. I'll write to him tonight. He loves a hopeless project.","mono":false,"off":810.4473,"dur":3.456,"env":"14882556655531255553257753002333443121343333210100000002656897134521157600023241002444311222110001000000"},"ep03_294":{"who":"NEMU","text":"Rank F. Look at you.","mono":false,"off":814.3033,"dur":1.621,"env":"0189874220488541111000000024960355103414321100000"},"ep03_295":{"who":"TAKUTO","text":"The clerk drew a star on mine.","mono":false,"off":816.3247,"dur":1.771,"env":"021012898400012334233116444333333333333211000000000000"},"ep03_296":{"who":"NEMU","text":"And a little crown.","mono":false,"off":818.4953,"dur":1.131,"env":"0269485384651022217665432110000000"},"ep03_297":{"who":"TAKUTO","text":"Valentine made her.","mono":false,"off":820.026,"dur":1.365,"env":"00699977765062567656566555411133100000000"},"ep03_298":{"who":"WICK","text":"Hey, Takuto. When you find your friend... can I come?","mono":false,"off":821.7913,"dur":2.731,"env":"0367764142697202742468764355665214755535411156443332100001155555201144321100000000"},"ep03_299":{"who":"TAKUTO","text":"Why?","mono":false,"off":824.922,"dur":0.619,"env":"0138998755432000000"},"ep03_300":{"who":"WICK","text":"Because I want to see somebody get what they're looking for. Just once. It'd be nice.","mono":false,"off":825.9407,"dur":4.437,"env":"06219737876468855533335553332675646755532374225620366553562024430024333222100127753112554321222100000000165653255455543111121100000000"},"ep03_301":{"who":"TAKUTO","text":"...Yeah. You can come.","mono":false,"off":830.778,"dur":1.173,"env":"023999642344112644222665311100000000"},"ep03_302":{"who":"NEMU","text":"Hm. You're collecting strays.","mono":false,"off":832.3513,"dur":2.24,"env":"07962034427998643100000000000076043868950005675342236653211001321000"},"ep03_303":{"who":"TAKUTO","text":"Says the girl I found on the train tracks.","mono":false,"off":834.9913,"dur":2.368,"env":"001299531441168998653244300065444434334320214444432112431000002110000000"},"ep03_304":{"who":"NEMU","text":"I found you.","mono":false,"off":837.7593,"dur":0.917,"env":"0269311188999985534311000000"},"ep03_305":{"who":"AKURO","text":"Something herded that beast to you, boy. Something that knows exactly what I am.","mono":true,"off":839.0767,"dur":5.824,"env":"0133488763035665642222579765674214775211024345423321232343658553124786674321100000000012369863113698555676336788757755322342222333577642001254553334664444444434444332211000000"},"ep03_306":{"who":"TAKUTO","text":"...Who?","mono":false,"off":845.3007,"dur":0.619,"env":"0022499965432100000"},"ep03_307":{"who":"AKURO","text":"Someone who smells like static.","mono":true,"off":846.3193,"dur":1.92,"env":"0024787579797543323468876642466531222114777664332100000000"},"ep03_308":{"who":"SABLE","text":"It broke a Behemoth on his third day.","mono":false,"off":848.6393,"dur":3.008,"env":"0001420159752231222112332332332210000122333564102333221012222211100000000000000000000000000"},"ep03_309":{"who":"SABLE","text":"...Faster than I hoped. Let's give the Guild something to worry about.","mono":false,"off":852.0473,"dur":4.288,"env":"001111997553343334333321243421000110000000147841342134212211323321366444221123321111233332322211221222101100000000000000000000000"},"ep03_310":{"who":"TAKUTO","text":"Next time: the Guild's artificer builds me a chain harness.","mono":false,"off":856.7353,"dur":3.456,"env":"02564023016776643211000321379851141356764521032232332111455431113433202322333333312443211000011000000000"},"ep03_311":{"who":"TAKUTO","text":"It lets my axe block exactly once. Once.","mono":false,"off":860.5913,"dur":3.093,"env":"043348981131566543144541120025553103222256544000343335543210121100000000013565321012110000000"},"ep03_312":{"who":"TAKUTO","text":"Then somebody sets the forge on fire, and a man in a black suit is smiling in the smoke.","mono":false,"off":864.0847,"dur":5.525,"env":"0037765233797763973532322863022034100266665313544330000776643211100000000000256665656666665553145665300323254320013333320344455553322222222223210455421000000000000000"},"ep03_313":{"who":"TAKUTO","text":"Episode four. Cogwheel Heart.","mono":false,"off":870.01,"dur":1.963,"env":"05721655599852111278875432011478742356543225664210000000000"}}};
